<div class="d-flex flex-wrap justify-content-between gap-3 align-items-center mb-3"><div><h1 class="h3">Indicadores y reportes</h1><p class="text-muted mb-0"><?= $user['rol']==='vendedor' ? 'Tu inventario y tus consultas, visitas, reservas y cierres asignados.' : 'Resumen de la actividad del equipo inmobiliario.' ?></p></div><?php if ($report): ?><a class="btn btn-outline-primary" href="<?= BASE_URL ?>/reports/export?<?= e(http_build_query(['from'=>$from,'to'=>$to])) ?>">Exportar resumen CSV</a><?php endif; ?></div>
<form class="card card-body mb-4" method="get" action="<?= BASE_URL ?>/reports"><div class="row g-3"><div class="col-md-5"><label class="form-label" for="from">Desde (incluido)</label><input class="form-control" id="from" name="from" type="date" required value="<?= e($from) ?>"></div><div class="col-md-5"><label class="form-label" for="to">Hasta (incluido)</label><input class="form-control" id="to" name="to" type="date" required value="<?= e($to) ?>"></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary">Consultar</button></div></div><p class="form-text mb-0">Hasta 366 días. Por defecto se muestra el mes actual hasta hoy, en hora de Lima.</p></form>
<?php if ($errors): ?><div class="alert alert-danger" role="alert"><?php foreach ($errors as $error): ?><p class="mb-0"><?= e($error) ?></p><?php endforeach; ?></div><?php endif; ?>
<?php if ($report): ?>
<div class="row g-3 mb-4"><?php foreach ($report['totals'] as $label=>$total): ?><div class="col-6 col-lg"><div class="card card-body h-100"><span class="small text-muted"><?= e($label) ?></span><strong class="display-6"><?= (int)$total ?></strong></div></div><?php endforeach; ?></div>
<div class="alert alert-light border small">El inventario refleja el estado actual y no depende de las fechas. Las consultas y reservas se filtran por fecha de creación; las visitas, por fecha programada; los cierres, por fecha de cierre. Los estados mostrados son los actuales: este reporte no reconstruye estados históricos ni calcula conversiones de una misma cohorte.</div>
<div class="row g-4 mb-4">
<?php $groups=['inventory'=>['Inventario actual',['disponible'=>'Disponible','reservado'=>'Reservado','vendido'=>'Vendido','alquilado'=>'Alquilado']], 'leads'=>['Consultas recibidas por etapa',Lead::STAGES], 'visits'=>['Visitas del período por estado',Visit::STATES], 'reservations'=>['Reservas solicitadas por estado',Reservation::STATES]]; ?>
<?php foreach ($groups as $key=>[$title,$labels]): ?><section class="col-md-6"><div class="card card-body h-100"><h2 class="h5 mb-3"><?= e($title) ?></h2><?php $total=array_sum($report[$key]); foreach ($labels as $value=>$label): $count=$report[$key][$value] ?? 0; ?><div class="d-flex justify-content-between small mt-2"><span><?= e($label) ?></span><strong><?= (int)$count ?></strong></div><div class="progress mt-1" style="height:7px" aria-hidden="true"><div class="progress-bar" style="width:<?= $total ? round($count/$total*100,1) : 0 ?>%"></div></div><?php endforeach; ?></div></section><?php endforeach; ?>
</div>
<section class="card card-body mb-4"><h2 class="h5">Montos de operaciones cerradas</h2><p class="small text-muted">Montos pactados, sin incluir cobros o comisiones. Las rentas mensuales se suman entre sí; no representan ingresos acumulados del período. Las monedas se presentan por separado.</p><?php if (!$report['amounts']): ?><p class="mb-0 text-muted">No se registraron cierres en el rango seleccionado.</p><?php else: ?><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Operación</th><th>Moneda</th><th>Cierres</th><th>Monto pactado</th></tr></thead><tbody><?php foreach ($report['amounts'] as $item): ?><tr><td><?= e(Closing::TYPES[$item['tipo']]) ?><?= $item['tipo']==='alquiler' ? ' (renta mensual)' : '' ?></td><td><?= e($item['moneda']) ?></td><td><?= (int)$item['total'] ?></td><td><?= number_format((float)$item['monto'],0) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="card card-body"><h2 class="h5">Últimos cierres del período</h2><?php if (!$report['recent']): ?><p class="text-muted mb-0">Aún no hay operaciones cerradas en estas fechas.</p><?php else: ?><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Fecha</th><th>Cliente / Inmueble</th><th>Operación</th><th>Monto</th><th>Detalle</th></tr></thead><tbody><?php foreach ($report['recent'] as $item): ?><tr><td><?= e($item['fecha_cierre']) ?></td><td><?= e($item['cliente']) ?><div class="small text-muted"><?= e($item['titulo']) ?></div></td><td><?= e(Closing::TYPES[$item['tipo']]) ?></td><td><?= e($item['moneda']) ?> <?= number_format((float)$item['monto_final'],0) ?><?= $item['tipo']==='alquiler' ? ' / mes' : '' ?></td><td><a href="<?= BASE_URL ?>/closings/show?id=<?= (int)$item['id'] ?>">Ver cierre</a></td></tr><?php endforeach; ?></tbody></table></div><p class="small text-muted mt-2 mb-0">Hasta 20 registros, de fecha más reciente a más antigua.</p><?php endif; ?></section>
<?php endif; ?>
